export function latLonToRioWorld(
  lat: number,
  lon: number
): [number, number] {
  const rawKmX = (lon - RIO_GEO_CONFIG.centerLon) * (RIO_GEO_CONFIG.kmPerDegLon ?? 90);
  const rawKmZ = -(lat - RIO_GEO_CONFIG.centerLat) * (RIO_GEO_CONFIG.kmPerDegLat ?? 111.1);
  const distKm = Math.hypot(rawKmX, rawKmZ);
  const coreRadiusKm = RIO_GEO_CONFIG.coreRadiusKm ?? 7.5;
  const worldUnitsPerKm = RIO_GEO_CONFIG.worldUnitsPerKm ?? 10.8;
  let effectiveKm = distKm;
  if (distKm > coreRadiusKm) {
    effectiveKm = coreRadiusKm + Math.log1p((distKm - coreRadiusKm) * 0.30) * 5.6;
  }
  const scale = distKm > 0.0001 ? (effectiveKm / distKm) * worldUnitsPerKm : worldUnitsPerKm;
  return [Math.round(rawKmX * scale * 100) / 100, Math.round(rawKmZ * scale * 100) / 100];
}

